local CanvasGroup = CS.UnityEngine.CanvasGroup
local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')

---@class UIMainInteractionOrderFoodNode
---@field ImgLikeability                	UnityEngine.RectTransform               
---@field Select                        	UnityEngine.RectTransform               
---@field ImgNew                        	UnityEngine.RectTransform               
