---@field Button                        	UnityEngine.RectTransform                                                    
local UIMainInteractionOrderFoodNode = Class("UIMainInteractionOrderFoodNode")
function UIMainInteractionOrderFoodNode:__init() 
    self._data = nil
    self._curRoleId = nil
    self._cb = nil
end

function UIMainInteractionOrderFoodNode:__delete()
    self._data = nil
    self._curRoleId = nil
    self._cb = nil
end

function UIMainInteractionOrderFoodNode:Awake()
    SetButtonAction(self.Button, Bind(self, self.OnClick))
end

function UIMainInteractionOrderFoodNode:Start()

end

function UIMainInteractionOrderFoodNode:Refresh(data, roleId, cb)
    if not data then
        return
    end
    self._data = data
    self._curRoleId = roleId
    self._cb = cb

    self:FillSelf()
end

function UIMainInteractionOrderFoodNode:FillSelf()
    self:RefreshSelect(false)
    local isUnlock = CookingUtils.IsUnlockFood(self._data.id)
    local isActivate = CookingUtils.IsHasActivateFood(self._data.id)

    CfUtils.FillText(self.TxtName, self._data.name)
    CfUtils.FillImage(self.ImgIcon, self._data.picture) 
    KTool.SetActive(self.ImgLikeability, PhoneUtils.IsRoleLikeFood(self._curRoleId, self._data.id))
    KTool.SetActive(self.SpecialFeelingUp, PhoneUtils.IsRoleLikeFood(self._curRoleId, self._data.id))
    CfUtils.FillText(self.TextNumber2, checkInt(PhoneUtils.GetOrderFavorabilityAdd() * 100).."%")

    CfUtils.FillText(self.TextNumber3, "x"..PhoneUtils.GetRoleAddNum(self._curRoleId, self._data.id))--  self._data.love)
    CfUtils.FillText(self.TextNumber, "x"..self._data.coinNum)
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(self._data.coinId)
    CfUtils.FillImage(self.ConsumeIcon, path)

    
    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CookingComponent)
    KTool.SetActive(self.Lock, not isUnlock or not isActivate)
    KTool.SetActive(self.Button.transform:Find("Unlock"), isUnlock and isActivate)

    KTool.SetActive(self.ImgLockBg, not isUnlock)
    KTool.SetActive(self.BtnUnlock, not isActivate and isUnlock)

    if isUnlock then
        KTool.SetActive(self.Lock.transform:Find("ImgIcon"), false)
        --未激活
        if not isActivate then
            local path = GoodsConfMgr:GetInstance():GetPhotoPathById(self._data.unlockCoinId)
            CfUtils.FillText(self.TxtNumber, self._data.unlockCoinNum)
            CfUtils.FillImage(self.ConsumeIconLock, path)
        end
    else
        KTool.SetActive(self.Lock.transform:Find("ImgIcon"), true)
        CfUtils.FillImage (self.Lock.transform:Find("ImgIcon"), self._data.picture)
        CfUtils.FillText(self.TxtLock, CookingUtils.GetUnlockFoodErr(self._data.id))
    end

    local isRoleLike = PhoneUtils.IsRoleLikeFood(self._curRoleId, self._data.id, true)
    KTool.SetActive(self.ImgLikeability, isRoleLike)
end

function UIMainInteractionOrderFoodNode:RefreshSelect(isTrue)
    KTool.SetActive(self.Select, isTrue)
end

function UIMainInteractionOrderFoodNode:OnClick()
    if not self._cb then
        return
    end
    if not CookingUtils.IsUnlockFood(self._data.id) then
        --ameUtils.Toast(localize("该食物未解锁"))
        GameUtils.ShowCommonGoodsTipsBoard(self.controller.gameObject, self._data.id, false)
        return
    elseif not CookingUtils.IsHasActivateFood(self._data.id) then
        self:ActivateFood()
        return
    end
    self._cb()
end

function UIMainInteractionOrderFoodNode:ActivateFood()
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.unlockCoinId)
    local consumes = {
        {
            goodsId = self._data.unlockCoinId,
            goodsNum = self._data.unlockCoinNum,
        }
    }
    GameUtils.SecondConfirm(localize("是否消耗_name_x_num_解锁料理", {_name_ = goodsVo.name, _num_ = self._data.unlockCoinNum}), function()
        local consume, errTips = GoodsUtils.CheckGoodConsume(consumes)
        if errTips then
            GameUtils.Toast(errTips)
            return
        end

        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CookingComponent)
        comp:ActivateFoodReq(self._data.id, function()
            self:FillSelf()

            for k, v in pairs(consumes) do
                v.num = v.goodsNum
            end
            GoodsUtils.ConsumeGoods(consumes, true)

            UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
                data = self._data,
                roleId = self._curRoleId,
                levelUpType = Constants.UICultivateLevelUpFinishType.LikeabilityFood
            }})
        end)
    end)
end

function UIMainInteractionOrderFoodNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainInteractionOrderFoodNode
